private static MailMessage BuildHtmlMail(string toEmail, string subject, string htmlBody)
{
    string fromEmail = GetTiemChungMailSetting("TiemChung_MailFrom", "tiemchung@tamduchearthospital.com");
    MailAddress fromAddress = new MailAddress(fromEmail);

    MailMessage message = new MailMessage();
    message.From = fromAddress;
    message.Sender = fromAddress;
    message.To.Add(new MailAddress(toEmail));
    message.Subject = subject;
    message.SubjectEncoding = System.Text.Encoding.UTF8;
    message.Body = htmlBody;
    message.BodyEncoding = System.Text.Encoding.UTF8;
    message.IsBodyHtml = true;
    message.Priority = MailPriority.High;
    return message;
}

private static void SendMailMessage(MailMessage message)
{
    string defaultFrom = "tiemchung@tamduchearthospital.com";
    string host = GetTiemChungMailSetting("TiemChung_MailHost", "smtp.gmail.com");
    int port = GetTiemChungMailPort();
    string userName = GetTiemChungMailSetting("TiemChung_MailUser", defaultFrom);
    string password = GetTiemChungMailSetting("TiemChung_MailPass", string.Empty);
    bool enableSsl = GetTiemChungMailEnableSsl();

    if (string.IsNullOrEmpty(password))
        throw new InvalidOperationException("Chua cau hinh TiemChung_MailPass trong appSettings.");

    using (SmtpClient smtp = new SmtpClient())
    {
        smtp.Host = host;
        smtp.Port = port;
        smtp.EnableSsl = enableSsl;
        smtp.DeliveryMethod = SmtpDeliveryMethod.Network;
        smtp.UseDefaultCredentials = false;
        smtp.Credentials = new NetworkCredential(userName, password);
        smtp.Send(message);
    }
}

private static string GetTiemChungMailSetting(string key, string defaultValue)
{
    string value = ConfigurationManager.AppSettings[key];
    if (string.IsNullOrWhiteSpace(value))
        return defaultValue;
    return value.Trim();
}

private static int GetTiemChungMailPort()
{
    string value = ConfigurationManager.AppSettings["TiemChung_MailPort"];
    int port;
    if (int.TryParse(value, out port) && port > 0)
        return port;
    return 587;
}

private static bool GetTiemChungMailEnableSsl()
{
    string value = ConfigurationManager.AppSettings["TiemChung_MailEnableSsl"];
    if (string.IsNullOrWhiteSpace(value))
        return true;

    value = value.Trim();
    if (string.Equals(value, "true", StringComparison.OrdinalIgnoreCase)
        || string.Equals(value, "1", StringComparison.OrdinalIgnoreCase))
        return true;
    if (string.Equals(value, "false", StringComparison.OrdinalIgnoreCase)
        || string.Equals(value, "0", StringComparison.OrdinalIgnoreCase))
        return false;
    return true;
}

