private static string GetMailErrorText(Exception ex)
{
    if (ex == null)
        return string.Empty;

    System.Text.StringBuilder sb = new System.Text.StringBuilder();
    SmtpException smtpEx = ex as SmtpException;
    if (smtpEx != null)
        sb.Append("SMTP ").Append(smtpEx.StatusCode).Append(": ").Append(smtpEx.Message);
    else
        sb.Append(ex.Message);

    if (ex.InnerException != null && !string.IsNullOrEmpty(ex.InnerException.Message))
        sb.Append(" | ").Append(ex.InnerException.Message);

    string text = sb.ToString();
    if (text.Length > 400)
        text = text.Substring(0, 400);
    return text;
}

