private static string GetMailErrorText(Exception ex)
{
    if (ex == null)
        return string.Empty;

    string detail = BuildMailExceptionDetail(ex);
    string hint = ClassifyMailError(detail);
    string host = GetTiemChungMailSetting("TiemChung_MailHost", "mail.tamduchearthospital.com");
    int port = GetTiemChungMailPort();
    string userName = GetTiemChungMailSetting("TiemChung_MailUser", "tiemchung@tamduchearthospital.com");
    bool hasPass = !string.IsNullOrEmpty(GetTiemChungMailSetting("TiemChung_MailPass", string.Empty));

    string text = string.Format(
        "{0} [host={1}; port={2}; user={3}; coMatKhau={4}] {5}",
        hint,
        host,
        port,
        userName,
        hasPass ? "co" : "KHONG",
        detail);
    if (text.Length > 500)
        text = text.Substring(0, 500);
    return text;
}

private static string BuildMailExceptionDetail(Exception ex)
{
    System.Text.StringBuilder sb = new System.Text.StringBuilder();
    SmtpException smtpEx = ex as SmtpException;
    if (smtpEx != null)
        sb.Append("SMTP ").Append(smtpEx.StatusCode).Append(": ").Append(smtpEx.Message);
    else
        sb.Append(ex.Message);

    if (ex.InnerException != null && !string.IsNullOrEmpty(ex.InnerException.Message))
        sb.Append(" | ").Append(ex.InnerException.Message);
    return sb.ToString();
}

private static string ClassifyMailError(string detail)
{
    string text = detail == null ? string.Empty : detail.ToLowerInvariant();

    if (ContainsMailError(text, "tiemchung_mailpass") || ContainsMailError(text, "chua cau hinh"))
        return "Thieu mat khau cau hinh Web.config.";

    if (ContainsMailError(text, "535")
        || ContainsMailError(text, "5.7.8")
        || ContainsMailError(text, "authentication")
        || ContainsMailError(text, "not authenticated")
        || ContainsMailError(text, "username and password")
        || ContainsMailError(text, "credentials")
        || ContainsMailError(text, "login"))
        return "Sai user hoac mat khau SMTP.";

    if (ContainsMailError(text, "mustissuestarttlsfirst")
        || ContainsMailError(text, "secure connection")
        || ContainsMailError(text, "starttls")
        || ContainsMailError(text, "ssl"))
        return "Loi SSL/TLS (sai cong hoac EnableSsl).";

    if (ContainsMailError(text, "timed out")
        || ContainsMailError(text, "timeout")
        || ContainsMailError(text, "unable to connect")
        || ContainsMailError(text, "connection refused")
        || ContainsMailError(text, "no connection could be made"))
        return "Khong ket noi duoc SMTP (host/cong/chan IP).";

    if (ContainsMailError(text, "relay")
        || ContainsMailError(text, "not permitted")
        || ContainsMailError(text, "5.7.1")
        || ContainsMailError(text, "550"))
        return "Server tu choi gui (chan relay/IP).";

    if (ContainsMailError(text, "certificate"))
        return "Loi chung chi SSL.";

    return "Loi SMTP chua phan loai.";
}

private static bool ContainsMailError(string text, string token)
{
    if (string.IsNullOrEmpty(text) || string.IsNullOrEmpty(token))
        return false;
    return text.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0;
}

